"""Choreo trajectories (bench/choreo/*.traj, generated by the official Choreo v2027.0.0-alpha-3 CLI) and two
ways to follow them.

ChoreoLib: port of ChoreoLib (github.com/SleipnirGroup/Choreo, tag v2027.0.0-alpha-3, 3a9e15f):
- trajectory/Trajectory.sampleInternal (binary search, clamp to the first/last sample) and
  SwerveSample.interpolate (integrates the earlier sample's acceleration over tau, not a linear blend);
- auto/AutoTrajectory cmdInitialize / cmdExecute / cmdIsFinished / cmdEnd: a timer from the command start,
  finished once timer > total time, and on a normal end the controller is called once more with the final
  sample. The bench then applies zero speeds (the drivetrain's default command);
- the controller is the one ChoreoLib's documentation gives (docs/choreolib/getting-started.md):
  field speeds = sample speeds + PID(10, 0, 0) on x and y + PID(7.5, 0, 0) on heading (continuous input).
  ChoreoLib itself ships no controller; this is the documented example every team starts from.

ChoreoHybrid ("Choreo geometry + DriveToPose finish") is a PROTOTYPE of a hybrid, not ours v2:
- the .traj samples are resampled by arc length into a polyline with speed and heading along it;
- progress is the robot's projection onto that polyline (bounded window around the last projection);
- along the path: speed = min(Choreo's speed at s + v * 50 ms, DriveToPose's brake sqrt(2 a (d - v * 50 ms))
  on the remaining arc length); across: P 5 on cross-track error; heading: Choreo's heading at s plus
  P 5, plus Choreo's speed * dtheta/ds as feedforward;
- within FINISH_RADIUS of the end it hands over to DriveToPose's law on the final pose (the same
  DriveToPose port as the chain baseline, DECEL 6); every output goes through the AccelerationLimiter at its
  shipped MU 1.0 (9.81 m/s^2) so the switch is seamless. Choreo plans corners at up to cof * g sideways; with
  the limiter at 6 m/s^2 (tried first) the prototype could not hold Choreo's curves (8-13 cm RMS off its own
  path on the S-curve, slalom and 12 m route, 31-47 cm past the end), so the limiter keeps its MU 1.0.
"""

import bisect
import json
import math
import os

import numpy as np

from common import Limits, clamp, wrap
from followers.base import AccelerationLimiter, Follower

CHOREO_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "choreo")


def load_traj(course_name):
    from courses import CHOREO_TRAJ

    name = CHOREO_TRAJ[course_name]
    with open(os.path.join(CHOREO_DIR, name + ".traj")) as fh:
        data = json.load(fh)
    samples = data["trajectory"]["samples"]
    if not samples:
        raise RuntimeError(f"{name}.traj has not been generated (run bench/choreo/make_project.py --cli ...)")
    return {"name": name, "samples": [(s["t"], s["x"], s["y"], s["heading"], s["vx"], s["vy"], s["omega"],
                                       s["ax"], s["ay"], s["alpha"]) for s in samples],
            # moduleForcesX / moduleForcesY, field frame, FL FR BL BR (absent from older files)
            "forces": [tuple(zip(s["fx"], s["fy"])) if "fx" in s else ((0.0, 0.0),) * 4 for s in samples]}


def forces_at(times, forces, t):
    """SwerveSample.interpolate's module forces: a linear blend of the two samples around t."""
    if t <= times[0]:
        return forces[0]
    if t >= times[-1]:
        return forces[-1]
    i = bisect.bisect_right(times, t)
    a, b = times[i - 1], times[i]
    u = 0.0 if b - a < 1e-6 else (t - a) / (b - a)
    return tuple((p[0] + (q[0] - p[0]) * u, p[1] + (q[1] - p[1]) * u) for p, q in zip(forces[i - 1], forces[i]))


def sample_at(samples, t):
    """Trajectory.sampleInternal + SwerveSample.interpolate: (t, x, y, heading, vx, vy, omega, ...)."""
    if t < samples[0][0]:
        return samples[0]
    if t >= samples[-1][0]:
        return samples[-1]
    lo, hi = 0, len(samples) - 1
    while lo != hi:
        mid = (lo + hi) // 2
        if samples[mid][0] < t:
            lo = mid + 1
        else:
            hi = mid
    if lo == 0:
        return samples[0]
    a, b = samples[lo - 1], samples[lo]
    if b[0] - a[0] < 1e-6:
        return b
    tau = t - a[0]
    t2 = tau * tau
    return (t, a[1] + a[4] * tau + 0.5 * a[7] * t2, a[2] + a[5] * tau + 0.5 * a[8] * t2,
            a[3] + a[6] * tau + 0.5 * a[9] * t2, a[4] + a[7] * tau, a[5] + a[8] * tau, a[6] + a[9] * tau,
            a[7], a[8], a[9])


def dense_geometry(samples, dt=0.005):
    """The path Choreo authored, sampled finely with the same interpolation (for metrics and resampling)."""
    T = samples[-1][0]
    out = [sample_at(samples, t) for t in np.arange(0.0, T, dt)] + [samples[-1]]
    return np.array([[s[1], s[2], s[3], math.hypot(s[4], s[5])] for s in out])


class ChoreoLib(Follower):
    """ff=True sends each sample's module forces as wheel force feedforward, as CTRE's Choreo example does
    (ApplyFieldSpeeds.withWheelForceFeedforwardsX/Y(sample.moduleForcesX/Y())). hold=True keeps the
    controller on the final sample once the clock runs out, until within 2 cm / hold_deg and under 5 cm/s
    (the same final hold PathPlanner gets): what a team adds when it wants the robot to end on the target."""

    ff_forces = None

    def __init__(self, kp=10.0, kp_rot=7.5, ff=False, hold=False, hold_deg=2.0, limits: Limits = Limits()):
        self.kp, self.kp_rot = kp, kp_rot
        self.ff, self.hold = ff, hold
        self.hold_rad = math.radians(hold_deg)  # the hold's heading tolerance
        self.lim = limits

    @staticmethod
    def adapt(course):
        return load_traj(course.name)

    @staticmethod
    def geometry(native):
        return dense_geometry(native["samples"])[:, :2]

    def reset(self, native, start):
        self.samples = native["samples"]
        self.forces = native.get("forces")
        self.times = [s[0] for s in self.samples]
        self.total = self.samples[-1][0]
        self.t0 = start.t
        self.state = "running"
        self.ff_forces = None

    def _control(self, s, pose):
        return (s[4] + self.kp * (s[1] - pose[0]), s[5] + self.kp * (s[2] - pose[1]),
                s[6] + self.kp_rot * wrap(s[3] - pose[2]))

    def step(self, t, pose, vel):
        self.ff_forces = None
        if self.state == "holding":
            g = self.samples[-1]
            ex, ey, eth = g[1] - pose[0], g[2] - pose[1], wrap(g[3] - pose[2])
            if math.hypot(ex, ey) < 0.02 and abs(eth) < self.hold_rad and math.hypot(vel[0], vel[1]) < 0.05:
                self.state = "done"
                return (0.0, 0.0, 0.0)
            return (self.kp * ex, self.kp * ey, self.kp_rot * eth)
        if self.state != "running":
            self.state = "done"
            return (0.0, 0.0, 0.0)
        now = t - self.t0
        out = self._control(sample_at(self.samples, now), pose)  # cmdExecute
        if self.ff and self.forces:
            self.ff_forces = forces_at(self.times, self.forces, now)
        if now > self.total:  # cmdIsFinished -> cmdEnd: the controller on the final sample, once
            out = self._control(self.samples[-1], pose)
            self.state = "holding" if self.hold else "ended"
        return out

    def done(self):
        return self.state == "done"


class ChoreoHybrid(Follower):
    """Prototype: Choreo geometry and speeds followed by position, DriveToPose finish (see module docstring)."""

    LATENCY = 0.05
    KP_CT, KP_ROT = 5.0, 5.0
    WINDOW = 0.5  # m of arc length searched around the last projection each loop
    FINISH_RADIUS = 0.30  # m of remaining arc length where DriveToPose takes over

    def __init__(self, limits: Limits = Limits()):
        self.lim = limits

    @staticmethod
    def adapt(course):
        return load_traj(course.name)

    @staticmethod
    def geometry(native):
        return dense_geometry(native["samples"])[:, :2]

    def reset(self, native, start):
        from followers.drive_to_pose_chain import DriveToPoseChain

        g = dense_geometry(native["samples"])
        d = np.hypot(*np.diff(g[:, :2], axis=0).T)
        keep = np.concatenate([[True], d > 1e-4])  # drop stationary samples so s is strictly increasing
        g = g[keep]
        s = np.concatenate([[0.0], np.cumsum(np.hypot(*np.diff(g[:, :2], axis=0).T))])
        # resample every 2 cm of arc length
        n = max(2, int(math.ceil(s[-1] / 0.02)) + 1)
        self.s = np.linspace(0.0, s[-1], n)
        self.x = np.interp(self.s, s, g[:, 0])
        self.y = np.interp(self.s, s, g[:, 1])
        self.h = np.interp(self.s, s, np.unwrap(g[:, 2]))
        self.v = np.interp(self.s, s, g[:, 3])
        self.L = float(s[-1])
        self.s_last = 0.0
        self.cmd = tuple(start.vel)
        self.goal = (float(self.x[-1]), float(self.y[-1]), float(wrap(self.h[-1])))
        self.dtp = DriveToPoseChain(limits=self.lim, traction=AccelerationLimiter.TRACTION)
        self.dtp.reset({"goals": [self.goal]}, start)
        self.finishing = False
        self.finished = False
        self.last_t = start.t
        self.sl = self.s.tolist()

    def _project(self, p):
        i0 = bisect.bisect_left(self.sl, self.s_last - self.WINDOW)
        i1 = bisect.bisect_right(self.sl, self.s_last + self.WINDOW)
        xs, ys = self.x[i0:i1], self.y[i0:i1]
        k = int(np.argmin((xs - p[0]) ** 2 + (ys - p[1]) ** 2)) + i0
        # refine on the neighbouring segment
        best = (self.s[k], k)
        for j in (k - 1, k):
            if 0 <= j < len(self.s) - 1:
                ax, ay, bx, by = self.x[j], self.y[j], self.x[j + 1], self.y[j + 1]
                dx, dy = bx - ax, by - ay
                l2 = dx * dx + dy * dy
                u = clamp(((p[0] - ax) * dx + (p[1] - ay) * dy) / l2, 0.0, 1.0) if l2 > 0 else 0.0
                qx, qy = ax + u * dx, ay + u * dy
                if (qx - p[0]) ** 2 + (qy - p[1]) ** 2 <= (self.x[best[1]] - p[0]) ** 2 + (self.y[best[1]] - p[1]) ** 2:
                    best = (self.s[j] + u * (self.s[j + 1] - self.s[j]), j)
        return float(best[0])

    def step(self, t, pose, vel):
        if self.finished:
            return (0.0, 0.0, 0.0)
        dt = clamp(t - self.last_t, 0.001, 0.1)
        self.last_t = t
        s = self._project(pose[:2])
        self.s_last = s
        remaining = self.L - s
        if not self.finishing and (remaining < self.FINISH_RADIUS
                                   or math.hypot(self.goal[0] - pose[0], self.goal[1] - pose[1]) < self.FINISH_RADIUS):
            self.finishing = True
            self.dtp._init_leg(t - dt, self.cmd)  # hand the current command to DriveToPose
        if self.finishing:
            self.cmd = self.dtp.step(t, pose, vel)
            self.finished = self.dtp.done()
            return self.cmd
        lim = self.lim
        now = math.hypot(self.cmd[0], self.cmd[1])
        v_path = float(np.interp(s + now * self.LATENCY, self.s, self.v))
        brake = math.sqrt(2 * lim.max_accel * max(0.0, remaining - now * self.LATENCY))
        speed = min(lim.max_speed, v_path, brake)
        # a stopped Choreo start (speed 0 at s = 0) would never move: give it the speed a little ahead
        if speed < 0.05 and remaining > self.FINISH_RADIUS:
            speed = max(speed, float(np.interp(s + 0.05, self.s, self.v)))
        i = min(int(np.searchsorted(self.s, s)), len(self.s) - 1)
        j = max(i - 1, 0)
        i = max(i, 1)
        tx, ty = self.x[i] - self.x[i - 1], self.y[i] - self.y[i - 1]
        tn = math.hypot(tx, ty) or 1.0
        tx, ty = tx / tn, ty / tn
        cx, cy = float(np.interp(s, self.s, self.x)), float(np.interp(s, self.s, self.y))
        cte = (pose[0] - cx) * -ty + (pose[1] - cy) * tx  # positive = left of the path
        vx = speed * tx + self.KP_CT * cte * ty
        vy = speed * ty - self.KP_CT * cte * tx
        h = float(np.interp(s, self.s, self.h))
        dh = (self.h[i] - self.h[j]) / max(self.s[i] - self.s[j], 1e-6)
        om = clamp(speed * dh + self.KP_ROT * wrap(h - pose[2]), -lim.max_omega, lim.max_omega)
        self.cmd = AccelerationLimiter.limit(self.cmd, (vx, vy, om), dt)
        return self.cmd

    def done(self):
        return self.finished
